import { getCustomer } from './customers.js';
import { formatEuros, roundCents } from './money.js';
import { lineTotal, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, issueDate: string, dueDate?: string, status: string, lines: Array, voucher?: object, payments?: Array }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const lines = [];

  // Header
  const invoiceNumber = invoice.number ?? 'DRAFT';
  lines.push(invoiceNumber);
  lines.push(customerName);

  // Line items
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const lineText = `  ${line.qty} x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    lines.push(lineText);

    // Line discount (if any)
    if (line.discountPercent > 0) {
      const discount = roundCents(total * line.discountPercent / 100);
      lines.push(`    Discount (${line.discountPercent}%): -${formatEuros(discount)}`);
    }
  }

  // Calculate totals
  const totals = invoiceTotals(invoice);

  // VAT line
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Voucher line (if any)
  if (invoice.voucher) {
    lines.push(`Voucher: -${formatEuros(invoice.voucher.amount)}`);
  }

  // Total
  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Due date line (if any)
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid line (if payments exist)
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}

